```cpp
#include <windows.h>
#include <wincrypt.h>
#include <iostream>

HRESULT DecryptDataWithDPAPI(LPBYTE pbData, DWORD cbData, LPBYTE* ppbDecrypted, DWORD* pcbDecrypted) {
    CRYPTPROTECT_PROMPT_INFO promptInfo = {0};
    promptInfo.cbSize = sizeof(CRYPTPROTECT_PROMPT_INFO);
    promptInfo.dwPromptFlags = 0;
    promptInfo.hwndApp = NULL;
    promptInfo.pszCaptionText = L"Decrypting Data...";
    promptInfo.pszDescriptionText = L"Please enter the password if required.";

    HRESULT hr = CryptUnprotectData(
        (DATA_BLOB*)pbData,
        NULL,
        NULL,
        &promptInfo,
        CRYPTPROTECT_UI_FORBIDDEN,
        (DATA_BLOB*)ppbDecrypted,
        pcbDecrypted
    );

    return hr;
}
```

> 注意：使用 `CRYPTPROTECT_UI_FORBIDDEN` 标志表示不显示提示框，适用于无用户交互的工具。

