### 2. **直接调用系统调用（NtXXX）函数**

#### 示例：隐藏进程（使用NtSetInformationProcess）

```c
#include <windows.h>
#include <ntdef.h>
#include <ntstatus.h>
#include <winternl.h>

typedef NTSTATUS (NTAPI *pNtSetInformationProcess)(
    _In_ HANDLE ProcessHandle,
    _In_ ULONG ProcessInformationClass,
    _In_ PVOID ProcessInformation,
    _In_ ULONG ProcessInformationLength
);

int main() {
    HMODULE hNtdll = GetModuleHandle("ntdll.dll");
    if (!hNtdll) return 1;

    pNtSetInformationProcess NtSetInformationProcess = (pNtSetInformationProcess)GetProcAddress(hNtdll, "NtSetInformationProcess");
    if (!NtSetInformationProcess) return 1;

    // Hide process from EDR
    ULONG ProcessInformationClass = ProcessBasicInformation;
    PVOID ProcessInformation = NULL; // 传入隐藏信息结构体
    ULONG ProcessInformationLength = 0;

    NTSTATUS status = NtSetInformationProcess(
        GetCurrentProcess(),
        ProcessInformationClass,
        ProcessInformation,
        ProcessInformationLength
    );

    if (NT_SUCCESS(status)) {
        printf("Process hidden successfully.\n");
    } else {
        printf("Failed to hide process. Status: 0x%08X\n", status);
    }

    return 0;
}
```

